15	/**
16	 * Common path limits.
17	 * While some OSs support longer, 4096 is a safe cross-platform limit for absolute paths.
18	 * Individual components are usually limited to 255.
19	 */
20	const MAX_PATH_LENGTH = 4096;
21	const MAX_COMPONENT_LENGTH = 255;
