23	/**
24	 * Validates a path string for common issues that lead to system-level crashes (like ENAMETOOLONG).
25	 * This is intended as a "pre-flight" check for paths derived from untrusted model output.
26	 */
27	export function validatePath(pathStr: string): PathValidationResult {
28	  if (!pathStr || typeof pathStr !== 'string') {
29	    return { isValid: false, error: 'Path must be a non-empty string.' };
30	  }
31	
32	  // Check for obviously invalid characters (newlines, control characters, null bytes)
33	  // These often appear when the model misinterprets logs as paths.
34	  if (/[\n\r\0\t]/.test(pathStr)) {
35	    return {
36	      isValid: false,
37	      error:
38	        'Path contains invalid characters (newlines or control characters).',
39	    };
40	  }
41	
42	  // Check for common log/error patterns that are definitely not paths.
43	  // We check for these at the start of the string OR at the start of any path component.
44	  // This ensures we catch them in both raw model output and resolved absolute paths.
45	  const logMarkerRegexes = [
46	    /(^|[/\\])AssertionError:/,
47	    /(^|[/\\])FAIL /,
48	    /(^|[/\\])✓ /,
49	    /(^|[/\\])× /,
50	    /(^|[/\\])TestingLibraryElementError:/,
51	  ];
52	  for (const regex of logMarkerRegexes) {
53	    if (regex.test(pathStr)) {
54	      return {
55	        isValid: false,
56	        error: 'Path appears to be a misinterpreted log fragment.',
57	      };
58	    }
59	  }
60	
61	  // Check for double quotes or ellipses in "paths" - almost always a misinterpretation if not a very short name.
62	  // We removed single quotes from this list to support users with apostrophes in their home directories.
63	  if (pathStr.includes('"') || pathStr.includes('...')) {
64	    if (pathStr.length > 20) {
65	      return {
66	        isValid: false,
67	        error:
68	          'Path contains suspicious characters (double quotes or ellipses) and is too long to be a simple filename.',
69	      };
70	    }
71	  }
72	
73	  // Check total length
74	  if (pathStr.length > MAX_PATH_LENGTH) {
75	    return {
76	      isValid: false,
77	      error: `Path is too long (maximum ${MAX_PATH_LENGTH} characters).`,
78	    };
79	  }
80	
81	  // Check individual component lengths
82	  const components = pathStr.split(/[/\\]/);
83	  for (const component of components) {
84	    if (component.length > MAX_COMPONENT_LENGTH) {
85	      return {
86	        isValid: false,
87	        error: `Path component "${component.substring(0, 20)}..." is too long (maximum ${MAX_COMPONENT_LENGTH} characters).`,
